// Musterlösung Pfad B: baut einen Tagesgruß als HTML-Seite.
// Deine eigene Version erzeugst du mit der Prompt-Vorlage vom Board.
const name = 'Kursteilnehmer:in';
const datum = new Date().toLocaleDateString('de-DE', {
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric',
  timeZone: 'Europe/Berlin',
});
const sprueche = [
  'Kleine Schritte sind auch Schritte.',
  'Automatisiere das Langweilige, damit Zeit für das Wichtige bleibt.',
  'Heute ist ein guter Tag für einen neuen Workflow.',
];
const spruch = sprueche[new Date().getDate() % sprueche.length];

const html = `<!DOCTYPE html>
<html lang="de">
<head>
<meta charset="utf-8">
<title>Guten Morgen!</title>
<style>
  body { margin: 0; min-height: 100vh; display: grid; place-items: center;
         font-family: system-ui, sans-serif; background: #1d2a3a; color: #f4f1ea; }
  .karte { max-width: 560px; padding: 48px; border-radius: 20px;
           background: #26374b; box-shadow: 0 20px 60px rgba(0,0,0,.35); }
  .datum { color: #f5a623; font-weight: 600; letter-spacing: .04em; }
  h1 { margin: 12px 0 24px; font-size: 40px; }
  blockquote { margin: 0; padding-left: 16px; border-left: 4px solid #f5a623;
               font-size: 20px; font-style: italic; }
</style>
</head>
<body>
  <div class="karte">
    <div class="datum">${datum}</div>
    <h1>Guten Morgen, ${name}!</h1>
    <blockquote>${spruch}</blockquote>
  </div>
</body>
</html>`;

return [{ json: { html } }];
